What is the output of the following C++ code?
try { throw 10; }
catch (int x) { cout << "int " << x; }
catch (...) { cout << "other"; }

What is the output of the following C++ code?
class A { public: virtual void f() { cout << "A"; } };
class B : public A { public: void f() { cout << "B"; } };
int main() { A *p = new B; p->f(); }

What is printed by this Java code?
String s = "Hi";
s.concat(" there");
System.out.println(s);

A text file in.txt contains: 10 20 30. What does this C++ code print?
ifstream f("in.txt");
int a, b;
f >> a >> b;
cout << a + b;

What is the output?
int x = 5;
int &r = x;
r++;
cout << x;

What is the output of this Java code?
int n = 2;
switch (n) {
  case 1: System.out.print("A");
  case 2: System.out.print("B");
  case 3: System.out.print("C"); break;
  default: System.out.print("D");
}

What does this Java code print?
int[][] a = new int[3][4];
System.out.print(a.length + " " + a[0].length);

